<?php
function renderJobReportAssets(bool $personal=false): void {
    static $done=false;if($done)return;$done=true;
    if($personal)echo '<link rel="stylesheet" href="'.htmlspecialchars(portalUiAssetUrl('assets/css/workspace-tabs.css'),ENT_QUOTES,'UTF-8').'"><script defer src="'.htmlspecialchars(portalUiAssetUrl('assets/js/workspace-tabs.js'),ENT_QUOTES,'UTF-8').'"></script>';
    echo '<link rel="stylesheet" href="'.htmlspecialchars(portalUiAssetUrl('assets/css/job-reports.css'),ENT_QUOTES,'UTF-8').'"><script defer src="'.htmlspecialchars(portalUiAssetUrl('assets/js/job-reports.js'),ENT_QUOTES,'UTF-8').'"></script>';
}
function renderJobReportWorkspace(bool $management=false): void {
    $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$today=new DateTimeImmutable('today',new DateTimeZone('Asia/Manila'));
    $config=['property'=>getPropertyInformation(),'endpoint'=>buildUrl('api/job_reports.php'),'export'=>buildUrl('job_report_export.php'),'csrf'=>workflowCsrfToken(),'scope'=>$management?'management':'personal','today'=>$today->format('Y-m-d'),'month'=>$today->format('Y-m'),'notes'=>JR_NOTES,'roles'=>array_intersect_key(getUserRoles(),array_flip(JR_ROLES)),'open_id'=>(int)($_GET['job_report']??0)];
    $activeTab=isset($_GET['tab'])&&is_string($_GET['tab'])&&in_array($_GET['tab'],['report','filed'],true)?$_GET['tab']:($config['open_id']?'filed':'report');
    ?>
    <div class="jr-workspace" data-job-reports<?= $management?'':' data-workspace-tabs' ?>>
    <script type="application/json" data-jr-config><?= json_encode($config,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?></script>
    <div class="jr-heading"><div><h2><?= $management?'Staff Reports':'My Job Report' ?></h2><p><?= $management?'Review filed staff reports, record feedback, and download authorized copies.':'Review, generate, and file your daily or monthly work activity reports.' ?></p></div></div>
    <p class="jr-message" data-jr-message role="status" aria-live="polite" hidden></p>
    <?php if(!$management): ?>
    <nav class="workspace-tabs" role="tablist" aria-label="My job report sections">
    <?php foreach(['report'=>'Job Report','filed'=>'My Filed Reports']as$key=>$label): ?><a href="<?= $e(buildUrl('job_report.php?tab='.$key)) ?>" role="tab" id="job-report-tab-<?= $key ?>" aria-controls="job-report-panel-<?= $key ?>" aria-selected="<?= $activeTab===$key?'true':'false' ?>" tabindex="<?= $activeTab===$key?'0':'-1' ?>" data-workspace-tab="<?= $key ?>"><?= $label ?></a><?php endforeach; ?>
    </nav>
    <section id="job-report-panel-report" role="tabpanel" aria-labelledby="job-report-tab-report" data-workspace-panel="report"<?= $activeTab==='report'?'':' hidden' ?>>
    <form class="jr-toolbar" data-jr-period data-loading="none"><label>Report type<select name="type"><option value="daily">Daily report</option><option value="monthly">Monthly report</option></select></label><label>Reporting period<input name="period" type="date" value="<?= $today->format('Y-m-d') ?>" max="<?= $today->format('Y-m-d') ?>" required></label><button type="submit">Load period</button><button type="button" class="jr-secondary" data-jr-refresh>Refresh report</button><span class="jr-muted">Asia/Manila</span></form>
    <div class="jr-stats" data-jr-summary aria-live="polite"></div><h3>My Work Summary</h3><div class="jr-stats" data-jr-role-summary></div>
    <section class="jr-card"><h3>System-Recorded Activity</h3><p class="jr-muted">Recorded work actions for this period. Logins and page visits are excluded. Repeated QR verifications for the same pass and outcome within 60 seconds count once.</p>
    <form class="jr-toolbar jr-filters" data-jr-activity-filters data-loading="none"><label>Search activities<input name="q" type="search" maxlength="120" placeholder="Work activity or reference"></label><label>Module<select name="module"><option value="">All modules</option></select></label><label>Activity type<select name="activity_type"><option value="">All activity types</option><option value="action">Actions & decisions</option><option value="update">Record updates</option><option value="verification">QR verification</option></select></label><label>Result<select name="result"><option value="">All results</option><option>Completed</option><option>Rejected</option><option>Refused</option></select></label><label>From time<input name="from_time" type="time"></label><label>To time<input name="to_time" type="time"></label><button type="submit">Filter</button><button type="button" class="jr-secondary" data-jr-clear-activities>Clear</button></form>
    <div data-jr-activities></div><p class="jr-muted">Completed Actions includes finalized decisions and successful verifications. Updated Records counts update events, rather than distinct records. Filtered timeline totals appear in its pager.</p></section>
    <section class="jr-card"><h3>Staff-Reported Work Notes</h3><p class="jr-muted">Describe additional work in your own words. These notes are separate from system-recorded activities. Avoid passwords, private resident details and confidential case information.</p><p data-jr-correction hidden class="jr-notice"></p>
    <form data-jr-notes data-loading="none"><div class="jr-note-grid"><?php foreach(JR_NOTES as$key=>$label): ?><label><?= $e($label) ?><textarea name="<?= $e($key) ?>" rows="4" maxlength="4000"></textarea></label><?php endforeach; ?></div><div class="jr-actions"><button type="button" data-jr-save>Save draft</button><button type="button" class="jr-secondary" data-jr-preview>Preview report</button><span class="jr-muted" data-jr-draft-state>Draft</span></div></form></section>
    </section>
    <?php endif; ?>
    <section class="jr-card"<?= $management?'':' id="job-report-panel-filed" role="tabpanel" aria-labelledby="job-report-tab-filed" data-workspace-panel="filed"'.($activeTab==='filed'?'':' hidden') ?>><h3><?= $management?'Filed Staff Reports':'My Filed Reports' ?></h3><p class="jr-muted">Each submitted version remains in the official record. Opening a report does not mark it reviewed.</p>
    <form class="jr-toolbar jr-filters" data-jr-file-filters data-loading="none"><label>Search <?= $management?'staff or report':'reports' ?><input name="q" type="search" maxlength="120" placeholder="<?= $management?'Staff ID, name, or report reference':'Report reference' ?>"></label>
    <?php if($management): ?><label>Staff role<select name="role"><option value="">All roles</option><?php foreach($config['roles']as$key=>$label): ?><option value="<?= $e($key) ?>"><?= $e($label) ?></option><?php endforeach; ?></select></label><?php endif; ?>
    <label>Type<select name="type"><option value="">Daily & monthly</option><option value="daily">Daily</option><option value="monthly">Monthly</option></select></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach(JR_STATUSES as$key=>$label): ?><option value="<?= $e($key) ?>"><?= $e($label) ?></option><?php endforeach; ?></select></label><label>Reporting day<input type="date" name="day" max="<?= $today->format('Y-m-d') ?>"></label><label>Reporting month<input type="month" name="month" max="<?= $today->format('Y-m') ?>"></label><label>Submission date<input type="date" name="submitted_date" max="<?= $today->format('Y-m-d') ?>"></label><label>Sort<select name="sort"><option value="newest">Newest first</option><option value="oldest">Oldest first</option></select></label><button type="submit">Search</button><button type="button" class="jr-secondary" data-jr-clear-files>Clear</button></form>
    <?php if($management): ?><div class="jr-stats" data-jr-review-summary></div><?php endif; ?>
    <div data-jr-files></div></section>
    <dialog class="jr-dialog" data-jr-dialog aria-label="Job report preview and review"><div class="jr-dialog-head"><h2 data-jr-dialog-title>Job Report</h2><button type="button" class="jr-close" data-jr-close aria-label="Close report"><?= systemIcon('close','system-action-icon') ?></button></div><p class="jr-message" data-jr-dialog-message role="status" hidden></p><template data-jr-brand><?= brandHtml('compact') ?><?= brandPropertyAddressHtml() ?></template><div data-jr-document></div><div class="jr-actions" data-jr-dialog-actions></div></dialog>
    </div>
    <?php
}
